from dataclasses import make_dataclass

@make_dataclass('A', [('fields', str, None)])
class A:
    def __post_init__(self):
        print('A post init!')
        if self.fields:
            self.fields = self.fields.split(',') if isinstance(self.fields, str) else self.fields

@make_dataclass('C', [('fields', str)], bases=(A,))
class C:
    pass

try:
    c = C(fields='a,b')
    print(f'Result: {c.fields}')
except Exception as e:
    print(f'ERROR: {e}')

# Try reverse - child declares the field
@make_dataclass('A2', [])  
class A2:
    def __post_init__(self):
        print('A2 post init!')
        if hasattr(self, 'fields') and self.fields:
            self.fields = self.fields.split(',') if isinstance(self.fields, str) else self.fields

@make_dataclass('C2', [('fields', str)], bases=(A2,))
class C2:
    pass

try:
    c2 = C2(fields='a,b') 
    print(f'Result2: {c2.fields}')
except Exception as e:
    print(f'ERROR2: {e}')
